  A["name: template"] --&gt; B["original dictionary"]
  C["name: alias"] --&gt; B
  D["name: shallow"] --&gt; E["new dictionary"]
  B --&gt; F["shared tasks list"]
  E --&gt; F
  G["name: independent"] --&gt; H["new dictionary"]
  H --&gt; I["new tasks list"]








